import { DateTime } from "luxon";

/**
 * The customer's calendar file, generated by us (Google never invites the customer).
 * METHOD:PUBLISH, no ATTENDEE. Same UID for the life of the booking; SEQUENCE grows
 * with each reschedule and on cancellation, so calendar apps update the one event.
 */
export type IcsBooking = {
  id: number;
  start_utc: string;
  end_utc: string;
  state: string;
  reschedule_count: number;
  meet_url: string | null;
  manageUrl: string;
  domain: string;
};

const basic = (iso: string) => DateTime.fromISO(iso, { zone: "utc" }).toFormat("yyyyMMdd'T'HHmmss'Z'");

/** RFC 5545 TEXT escaping. */
export function escapeText(s: string): string {
  return s.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
}

/** RFC 5545 line folding: at most 75 octets per line, never splitting a UTF-8 character. */
export function fold(line: string): string {
  const enc = new TextEncoder();
  const parts: string[] = [];
  let cur = "";
  let bytes = 0;
  let limit = 75;
  for (const ch of line) {
    const n = enc.encode(ch).length;
    if (bytes + n > limit) {
      parts.push(cur);
      cur = "";
      bytes = 0;
      limit = 74; // continuation lines start with a space
    }
    cur += ch;
    bytes += n;
  }
  parts.push(cur);
  return parts.join("\r\n ");
}

export function buildIcs(b: IcsBooking, now: DateTime = DateTime.utc()): string {
  const cancelled = b.state === "cancelled";
  const description = [
    "Durum Analizi — 90 dakika.",
    b.meet_url ? `Görüşme bağlantısı: ${b.meet_url}` : "Görüşme bağlantısı (Google Meet) e-postayla gönderilecek.",
    `Saati değiştirmek ya da iptal etmek için: ${b.manageUrl}`,
  ].join("\n");
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Üç Eksen//Randevu//TR",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    `UID:booking-${b.id}@${b.domain}`,
    `SEQUENCE:${b.reschedule_count + (cancelled ? 1 : 0)}`,
    `DTSTAMP:${basic(now.toISO()!)}`,
    `DTSTART:${basic(b.start_utc)}`,
    `DTEND:${basic(b.end_utc)}`,
    `SUMMARY:${escapeText(cancelled ? "İPTAL: Durum Analizi — Üç Eksen" : "Durum Analizi — Üç Eksen")}`,
    `DESCRIPTION:${escapeText(description)}`,
    ...(b.meet_url ? [`LOCATION:${escapeText(b.meet_url)}`, `URL:${b.meet_url}`] : []),
    "ORGANIZER;CN=Üç Eksen:mailto:merhaba@uceksen.com",
    `STATUS:${cancelled ? "CANCELLED" : "CONFIRMED"}`,
    "TRANSP:OPAQUE",
    ...(cancelled ? [] : ["BEGIN:VALARM", "ACTION:DISPLAY", "DESCRIPTION:Durum Analizi — 30 dakika sonra", "TRIGGER:-PT30M", "END:VALARM"]),
    "END:VEVENT",
    "END:VCALENDAR",
  ];
  return lines.map(fold).join("\r\n") + "\r\n";
}
